  }
  render(<React.StrictMode><App /></React.StrictMode>);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  expect(validate).toHaveBeenCalledTimes(1);
});

it('clears dirty state when a numeric controlled value returns to its initial value', () => {
  function App() {
    const [value, setValue] = React.useState(5);
    return (<Field.Root data-testid="root"><Field.Control value={value} onValueChange={(v) => setValue(Number(v))} /></Field.Root>);
  }
  render(<App />);
  const root = screen.getByTestId('root');
  const control = screen.getByRole('textbox');
  expect(root).not.toHaveAttribute('data-dirty');
  fireEvent.change(control, { target: { value: '56' } });
